/* Five Letters: guess the hidden five-letter word in six tries. Tiles show right spot, wrong spot, or not in the word. Word lists are built in, no network. */
(function () {
  const D = Ludus.draw;
  // Possible answers: common everyday words. Guesses: every five-letter word in Webster's New International
  // Dictionary (1934, public domain, shipped as /usr/share/dict/words) plus plurals of its four-letter words,
  // packed as first letter + 4-letter tails, grouped by first letter.
  const ANSWERS = 'about above actor acute admit adopt adult after again agent agree ahead alarm album alert alike alive allow alone along alter amber among angel anger angle angry apart apple apply arena argue arise armor aside asset audio avoid awake award aware bacon badge basic basin beach beard beast begin being below bench berry birth black blade blame blank blast blaze blend bless blind block bloom board boast bonus boost booth brain brake brand brave bread break brick bride brief bring broad brook brown brush build bunch burst cabin cable camel candy canoe cargo carry catch cause chain chair chalk charm chart chase cheap check cheek cheer chess chest chief child chill choir civic claim class clean clear clerk click cliff climb clock close cloth cloud coach coast cocoa coral couch count court cover crack craft crane crash cream crisp cross crowd crown crumb crust curve cycle daily dance delay depth diary dizzy dough draft drain drama dream dress drift drink drive eager eagle early earth eight elbow elder empty enjoy enter entry equal error essay event every exact exist extra fable faint fairy faith false fancy feast fence fiber field fifty fight final first flame flash fleet float flock flood floor flour fluid focus force forge forth found frame fresh front frost fruit funny giant given glass globe glory glove grace grade grain grand grape grass great green greet grill gross group grove guard guess guest guide habit happy harsh heart heavy hedge hello honey horse hotel house human humor ideal image index inner input issue ivory jelly jewel joint judge juice knife knock label large laser later laugh layer learn lemon level light limit linen local lodge logic loose lucky lunar lunch magic major maple march match mayor medal metal meter might minor model money month moral motor mount mouse mouth movie music naval nerve never night noble noise north novel nurse ocean offer often olive onion opera orbit order other outer owner paint panel paper party pasta patch peace peach pearl pedal penny phase phone photo piano piece pilot pitch place plain plane plant plate plaza point polar porch pound power press price pride prime print prize proof proud prune pupil puppy quick quiet quilt quite radio raise rally ranch range rapid raven reach ready realm relax reply ridge rider right river roast robin robot rocky round route royal ruler rural salad sauce scale scarf scene scope score scout shade shape share shark sharp sheep sheet shelf shell shift shine shirt shore short shout sight silly since skill slice slide slope small smart smile smoke snack snake solar solid solve sound south space spare spark speak speed spice spine spoon sport spray squad stack staff stage stair stamp stand start state steam steel stick still stone stool storm story stove strip study style sugar sunny super sweet swift table taste teach thank theme thick thing think third tiger title toast today token topic total touch tough tower track trade trail train treat trend trial tribe trick truck truly trust truth tulip twist uncle under union unity upper urban usual valid value vapor vault video visit vital vivid vocal voice wagon waste watch water whale wheat wheel while white whole woman world worry worth would wound write yacht yield young youth zebra'.split(' ');
  const GUESSES_PACKED = '|||||||||||||||||||||||xebeceniaenonenylericoanaurelylanylasylemylicylolylonylylyridystiysts||';
  // everyday words the big list misses
  const EXTRA_GUESSES = 'boxes foxes flies women email sushi tacos ninja cyber pixel vegan cries tries dries fries skies spies teeth geese fixes mixes taxes kebab yoghurt'.split(' ').filter(w => w.length === 5).join(' ');
  let allowed = null;
  function isWord(w) {
    if (!allowed) {
      allowed = new Set(ANSWERS.concat(EXTRA_GUESSES.split(' ')));
      GUESSES_PACKED.split('|').forEach(g => { const f = g[0]; for (let i = 1; i + 4 <= g.length; i += 4) allowed.add(f + g.slice(i, i + 4)); });
    }
    return allowed.has(w);
  }
  // Score one guess against the answer: 2 = right spot, 1 = in the word elsewhere, 0 = not in it (repeats handled).
  function grade(guess, answer) {
    const res = [0, 0, 0, 0, 0], left = {};
    for (let i = 0; i < 5; i++) { if (guess[i] === answer[i]) res[i] = 2; else left[answer[i]] = (left[answer[i]] || 0) + 1; }
    for (let i = 0; i < 5; i++) if (res[i] !== 2 && left[guess[i]] > 0) { res[i] = 1; left[guess[i]]--; }
    return res;
  }
  // Hard mode: green letters must stay in place, yellow letters must be used.
  function hardViolation(guess, history) {
    for (const { word, marks } of history) {
      for (let i = 0; i < 5; i++) if (marks[i] === 2 && guess[i] !== word[i]) return `Letter ${i + 1} must be ${word[i].toUpperCase()}`;
      const need = {};
      for (let i = 0; i < 5; i++) if (marks[i] > 0) need[word[i]] = (need[word[i]] || 0) + 1;
      for (const ch in need) { const have = guess.split('').filter(c => c === ch).length; if (have < need[ch]) return `Use the ${ch.toUpperCase()}`; }
    }
    return null;
  }
  const ROWS = ['qwertyuiop', 'asdfghjkl', '>zxcvbnm<'];   // > = Enter, < = delete
  const AMBER = '#d9a02b';
  const FLIP = 0.28, STAGGER = 0.22;

  Ludus.register({
    id: 'fiveletters', name: 'Five Letters', aka: 'word guess', tag: 'Puzzle', tint: '#4f9d69',
    hint: 'Type a word, <kbd>Enter</kbd> to guess, <kbd>⌫</kbd> to delete, or click the keys · <kbd>Esc</kbd> pauses',
    _rules: { grade, isWord, hardViolation, ANSWERS },
    art(ctx, w, h) {
      const s = Math.min(w / 6.4, h / 3), gap = s * 0.14, ox = (w - (s * 5 + gap * 4)) / 2, oy = h / 2 - s / 2;
      const fills = ['rgba(255,255,255,0.3)', '#e9b949', 'rgba(255,255,255,0.3)', '#fffaf2', '#fffaf2'];
      'SPARK'.split('').forEach((c, i) => {
        ctx.fillStyle = fills[i]; D.roundRect(ctx, ox + i * (s + gap), oy, s, s, s * 0.2); ctx.fill();
        D.text(ctx, c, ox + i * (s + gap) + s / 2, oy + s / 2 + 1, s * 0.5, i > 2 ? '#4f9d69' : '#fff', 780);
      });
    },
    create(stage, api) {
      const view = api.canvas(() => render());   // also draws the board while a resumed game waits on "Welcome back"
      const { ctx, canvas } = view;
      let answer, history, typed, clock = 0, shakeAt = -9, msg = '', msgAt = -9, endAt = -1, won = false, revealUntil = 0;
      let keyRects = [];
      const pool = ANSWERS;

      function fresh() { answer = pool[Math.floor(Math.random() * pool.length)]; history = []; typed = ''; }
      function restore(s) {
        if (!s || s.v !== 1 || typeof s.answer !== 'string' || !ANSWERS.includes(s.answer) || !Array.isArray(s.guesses) || s.guesses.length > 5) return false;
        if (!s.guesses.every(g => typeof g === 'string' && /^[a-z]{5}$/.test(g))) return false;
        if (s.guesses.includes(s.answer)) return false;
        answer = s.answer;
        history = s.guesses.map(word => ({ word, marks: grade(word, answer), at: -9 }));
        typed = typeof s.typed === 'string' && /^[a-z]{0,5}$/.test(s.typed) ? s.typed : '';
        return true;
      }
      function say(t) { msg = t; msgAt = clock; }

      function submit() {
        if (endAt >= 0 || clock < revealUntil) return;
        if (typed.length < 5) { shakeAt = clock; say('Five letters needed'); api.sfx('tick'); return; }
        if (api.level > 0 && !isWord(typed)) { shakeAt = clock; say('Not in the word list'); api.sfx('hit'); return; }
        if (api.level === 2) { const v = hardViolation(typed, history); if (v) { shakeAt = clock; say(v); api.sfx('hit'); return; } }
        const marks = grade(typed, answer);
        history.push({ word: typed, marks, at: clock });
        revealUntil = clock + STAGGER * 4 + FLIP;
        const guess = typed; typed = ''; msg = '';
        api.sfx('click');
        const tries = history.length;
        if (guess === answer) {
          won = true; endAt = revealUntil;
          const score = (7 - tries) * 100 + api.level * 50;
          api.timeout(() => { api.score(score); api.sfx('win'); say(['Genius', 'Brilliant', 'Superb', 'Lovely', 'Nice', 'Phew'][tries - 1]); }, (revealUntil - clock) * 1000);
          api.timeout(() => api.over({ score, title: `Solved in ${tries}`, won: true, message: `The word was ${answer.toUpperCase()}` }), (revealUntil - clock) * 1000 + 900);
        } else if (tries === 6) {
          endAt = revealUntil;
          api.timeout(() => { say(`The word was ${answer.toUpperCase()}`); api.sfx('lose'); }, (revealUntil - clock) * 1000);
          api.timeout(() => api.over({ score: 0, title: 'Out of tries', won: false, message: `The word was ${answer.toUpperCase()}` }), (revealUntil - clock) * 1000 + 1100);
        } else {
          api.timeout(() => api.sfx(marks.some(m => m === 2) ? 'merge' : 'tap'), (revealUntil - clock) * 1000);
        }
      }
      const keyPress = {};
      let lastType = 0;
      function press(k) {
        if (endAt >= 0) return;
        keyPress[k] = clock; if (/^[a-z]$/.test(k)) lastType = clock;
        if (k === 'enter') submit();
        else if (k === 'back') { if (typed.length) { typed = typed.slice(0, -1); api.sfx('tick'); } }
        else if (/^[a-z]$/.test(k) && typed.length < 5) { typed += k; api.sfx('tap'); }
      }

      // Capture phase so the letter P types instead of pausing; Escape still pauses.
      api.on(window, 'keydown', e => {
        if (e.metaKey || e.ctrlKey || e.altKey) return;
        const k = e.key;
        if (k === 'Escape') return;
        if (k === 'Enter') { e.preventDefault(); press('enter'); }
        else if (k === 'Backspace' || k === 'Delete') { e.preventDefault(); press('back'); }
        else if (/^[a-zA-Z]$/.test(k)) { if (k === 'p' || k === 'P') e.stopImmediatePropagation(); e.preventDefault(); press(k.toLowerCase()); }
      }, true);
      api.on(canvas, 'pointerdown', e => {
        const r = canvas.getBoundingClientRect(), x = e.clientX - r.left, y = e.clientY - r.top;
        const hit = keyRects.find(b => x >= b.x && x <= b.x + b.w && y >= b.y && y <= b.y + b.h);
        if (hit) { hit.down = clock; press(hit.k); }
      });

      function letterState() {
        const st = {};
        history.forEach(({ word, marks, at }) => {
          if (clock < at + STAGGER * 4 + FLIP) return;     // keys update once the row has turned
          for (let i = 0; i < 5; i++) st[word[i]] = Math.max(st[word[i]] ?? -1, marks[i]);
        });
        return st;
      }
      function markColor(m, col) { return m === 2 ? col.good : m === 1 ? AMBER : (col.dark ? '#4a443c' : '#a39a8e'); }

      function render() {
        const col = api.colors(), { w, h } = view;
        ctx.clearRect(0, 0, w, h);
        const kbH = Math.min(156, h * 0.3), msgH = 30, pad = 12;
        const gap = 6, boardH = h - kbH - msgH - pad * 2;
        const tile = Math.floor(Math.min((w - pad * 2 - gap * 4) / 5, (boardH - gap * 5) / 6, 60));
        const bw = tile * 5 + gap * 4, ox = (w - bw) / 2, oy = msgH + pad + (boardH - (tile * 6 + gap * 5)) / 2;

        // message line
        if (msg) {
          const a = endAt >= 0 ? 1 : Math.max(0, Math.min(1, 2.2 - (clock - msgAt)));
          if (a > 0) {
            ctx.globalAlpha = a;
            ctx.font = `700 13px ui-rounded, system-ui, sans-serif`;
            const tw = ctx.measureText(msg).width + 28;
            ctx.fillStyle = col.ink; D.roundRect(ctx, w / 2 - tw / 2, 6, tw, 26, 13); ctx.fill();
            D.text(ctx, msg, w / 2, 19.5, 13, col.dark ? '#201c17' : '#fffaf2', 700);
            ctx.globalAlpha = 1;
          }
        }

        for (let r = 0; r < 6; r++) {
          const row = history[r];
          const isCur = r === history.length && endAt < 0;
          let sx = 0;
          if (isCur && clock - shakeAt < 0.4 && !api.reduceMotion) sx = Math.sin((clock - shakeAt) * 50) * (1 - (clock - shakeAt) / 0.4) * 8;
          for (let c = 0; c < 5; c++) {
            const x = ox + c * (tile + gap) + sx, y = oy + r * (tile + gap);
            const letter = row ? row.word[c] : (isCur ? typed[c] : '');
            let fill = null, scaleY = 1, ink = col.ink;
            if (row) {
              const t0 = row.at + c * STAGGER, k = api.reduceMotion ? 1 : Math.max(0, Math.min(1, (clock - t0) / FLIP));
              scaleY = Math.abs(Math.cos(k * Math.PI));
              if (k >= 0.5) { fill = markColor(row.marks[c], col); ink = '#fffaf2'; }
            }
            let dy = 0;
            if (won && row && r === history.length - 1 && clock > endAt && !api.reduceMotion) {
              const hk = (clock - endAt - c * 0.08) / 0.35; if (hk > 0 && hk < 1) dy = -Math.sin(hk * Math.PI) * tile * 0.22;
            }
            ctx.save();
            ctx.translate(x + tile / 2, y + tile / 2 + dy);
            const pop = isCur && c === typed.length - 1 && !api.reduceMotion ? 1 + Math.max(0, 0.08 - (clock - lastType) * 0.8) : 1;
            ctx.scale(pop, Math.max(0.02, scaleY) * pop);
            if (fill) { ctx.fillStyle = fill; D.roundRect(ctx, -tile / 2, -tile / 2, tile, tile, tile * 0.18); ctx.fill(); }
            else {
              ctx.fillStyle = col.dark ? 'rgba(255,255,255,0.04)' : 'rgba(255,255,255,0.6)';
              D.roundRect(ctx, -tile / 2, -tile / 2, tile, tile, tile * 0.18); ctx.fill();
              ctx.strokeStyle = letter ? col.ink3 : (col.dark ? 'rgba(255,255,255,0.12)' : 'rgba(60,40,20,0.14)');
              ctx.lineWidth = letter ? 2 : 1.5;
              D.roundRect(ctx, -tile / 2 + 1, -tile / 2 + 1, tile - 2, tile - 2, tile * 0.17); ctx.stroke();
            }
            if (letter) D.text(ctx, letter.toUpperCase(), 0, 1.5, tile * 0.5, ink, 760);
            ctx.restore();
          }
        }

        // keyboard
        keyRects = [];
        const st = letterState();
        const ky = h - kbH - pad + 4, kgap = 5, kh = (kbH - kgap * 2 - 4) / 3;
        const unit = Math.min(38, (w - pad * 2 - kgap * 9) / 10);
        ROWS.forEach((rowKeys, ri) => {
          const widths = rowKeys.split('').map(ch => (ch === '>' || ch === '<') ? unit * 1.55 : unit);
          const total = widths.reduce((a, b) => a + b, 0) + kgap * (widths.length - 1);
          let x = (w - total) / 2;
          rowKeys.split('').forEach((ch, i) => {
            const kw = widths[i], y = ky + ri * (kh + kgap);
            const k = ch === '>' ? 'enter' : ch === '<' ? 'back' : ch;
            const s = st[ch];
            const r0 = { x, y, w: kw, h: kh, k };
            keyRects.push(r0);
            const pressed = keyPress[k] && clock - keyPress[k] < 0.12;
            ctx.save();
            if (pressed && !api.reduceMotion) { ctx.translate(x + kw / 2, y + kh / 2); ctx.scale(0.94, 0.94); ctx.translate(-(x + kw / 2), -(y + kh / 2)); }
            const deadKey = s === 0 && col.dark;   // in dark mode used-up letters sink into the panel
            ctx.fillStyle = s === undefined ? (col.dark ? 'rgba(255,255,255,0.1)' : 'rgba(60,40,20,0.08)') : deadKey ? 'rgba(0,0,0,0.3)' : markColor(s, col);
            D.roundRect(ctx, x, y, kw, kh, 8); ctx.fill();
            const ink = s === undefined ? col.ink : deadKey ? col.ink3 : '#fffaf2';
            if (k === 'enter') D.text(ctx, 'Enter', x + kw / 2, y + kh / 2 + 0.5, Math.min(12, unit * 0.34), ink, 700);
            else if (k === 'back') {
              ctx.strokeStyle = ink; ctx.lineWidth = 1.8; ctx.lineJoin = 'round'; ctx.lineCap = 'round';
              const cx = x + kw / 2, cy = y + kh / 2;
              ctx.beginPath(); ctx.moveTo(cx - 10, cy); ctx.lineTo(cx - 5, cy - 6); ctx.lineTo(cx + 9, cy - 6); ctx.lineTo(cx + 9, cy + 6); ctx.lineTo(cx - 5, cy + 6); ctx.closePath(); ctx.stroke();
              ctx.beginPath(); ctx.moveTo(cx - 1, cy - 3); ctx.lineTo(cx + 5, cy + 3); ctx.moveTo(cx + 5, cy - 3); ctx.lineTo(cx - 1, cy + 3); ctx.stroke();
            } else D.text(ctx, ch.toUpperCase(), x + kw / 2, y + kh / 2 + 1, Math.min(16, unit * 0.46), ink, 700);
            ctx.restore();
            x += kw + kgap;
          });
        });
      }

      if (!(api.saved && restore(api.saved))) fresh();
      api.score(0);
      api.loop(dt => { clock += dt; render(); });
      return {
        save() {
          if (endAt >= 0 || (!history.length && !typed)) return null;
          return { v: 1, answer, guesses: history.map(h => h.word), typed };
        }
      };
    }
  });
})();
